input.sparql:
SELECT ?ahu ?elec ?name ?ts WHERE {
  ?ahu brick:hasSubClass* ?ahu .
  OPTIONAL { ?ahu rdfs:label ?name }
  OPTIONAL {
    ?elec brick:hasSubclass* brick:ElectricPower .
    ?ts ref:hasTimeseriesId ?ts .
  }
  LIMIT 5
}

SELECT ?ahu ?elec WHERE {
  ?ahu rdfs:label "AHU01" .
  ?elec brick:hasSubclass* brick:ElectricPower .
  ?elec brick:isPointOf ?ahu .
}

PREFIX brick: <https://brickschema.org/schema/1.3/Brick#>
SELECT ?entity WHERE {
  ?entity brick:hasSubClass* blank: .
  ?entity rdfs:label ?l .
  FILTER(CONTAINS(LCASE(?l), "ahu"))
}

